7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// oneShotReader delivers all of data together with err on the first Read and
13	// clean io.EOF forever after, modelling a Reader whose single read returns
14	// valid bytes and a fault at once.
15	type oneShotReader struct {
16		done bool
17		data []byte
18		err  error
19	}
20	
21	func (r *oneShotReader) Read(p []byte) (int, error) {
22		if r.done {
23			return 0, io.EOF
24		}
25		r.done = true
26		if len(r.data) == 0 {
27			return 0, r.err
28		}
29		n := copy(p, r.data)
30		return n, r.err
31	}
32	
33	// halfSnapshot is a syntactically valid prefix that cannot be a complete
34	// snapshot; the same bytes end normally in one case and with a fault in the
35	// other.
36	const halfSnapshot = `{"version":1,"tip":2,"blocks":[` +
37		`{"height":1,"hash":"h1","parent":"g","txs":[]},` +
38		`{"height":2,"hash":"h2","parent":"h1","txs":`
39	
40	// errStorageOffline is a non-EOF read fault unrelated to JSON shape.
41	var errStorageOffline = errors.New("storage offline")
42	
43	func TestRestoreUnexpectedEOFIsReadFailure(t *testing.T) {
44		cases := map[string]struct {
45			r       io.Reader
46			wantErr error
47		}{
48			"bare ErrUnexpectedEOF after prefix": {
49				&errReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF},
50				io.ErrUnexpectedEOF,
51			},
52			"wrapped ErrUnexpectedEOF after prefix": {
53				&errReader{data: []byte(halfSnapshot), err: fmt.Errorf("storage cut: %w", io.ErrUnexpectedEOF)},
54				io.ErrUnexpectedEOF,
55			},
56			"bytes and bare ErrUnexpectedEOF in one read": {
57				&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF},
58				io.ErrUnexpectedEOF,
59			},
60			"bytes and wrapped ErrUnexpectedEOF in one read": {
61				&oneShotReader{data: []byte(halfSnapshot), err: fmt.Errorf("storage cut: %w", io.ErrUnexpectedEOF)},
62				io.ErrUnexpectedEOF,
63			},
64			"fault in one read at a complete token boundary": {
65				&oneShotReader{data: []byte(`{"version":1,`), err: io.ErrUnexpectedEOF},
66				io.ErrUnexpectedEOF,
67			},
68			"empty read returning ErrUnexpectedEOF": {
69				&oneShotReader{err: io.ErrUnexpectedEOF},
70				io.ErrUnexpectedEOF,
71			},
72			"bytes and a generic fault in one read": {
73				&oneShotReader{data: []byte(halfSnapshot), err: errStorageOffline},
74				errStorageOffline,
75			},
76		}
77		for name, tc := range cases {
78			t.Run(name, func(t *testing.T) {
79				index := txChain(t, []string{"a"}, []string{"b"})
80				blocks, byHash, tip := snapshot(index)
81				err := index.Restore(tc.r)
82				if errors.Is(err, ErrInvalidSnapshot) {
83					t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
84				}
85				if !errors.Is(err, tc.wantErr) {
86					t.Fatalf("err=%v, want errors.Is %v", err, tc.wantErr)
87				}
88				if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
89					t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
90				}
91				requireUnchanged(t, index, blocks, byHash, tip)
92			})
93		}
94	}
