123	func TestRestoreSameHalfBytesCleanEOFVsFault(t *testing.T) {
124		// Normal end after the same half document: truncated content, not a read
125		// failure.
126		index := txChain(t, []string{"a"}, []string{"b"})
127		err := index.Restore(strings.NewReader(halfSnapshot))
128		if !errors.Is(err, ErrInvalidSnapshot) {
129			t.Fatalf("clean EOF: err=%v, want ErrInvalidSnapshot", err)
130		}
131	
132		// Read failure on the same bytes: a different error category.
133		index = txChain(t, []string{"a"}, []string{"b"})
134		err = index.Restore(&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF})
135		if errors.Is(err, ErrInvalidSnapshot) {
136			t.Fatalf("fault: err=%v, must not be ErrInvalidSnapshot", err)
137		}
138		if !errors.Is(err, io.ErrUnexpectedEOF) {
139			t.Fatalf("fault: err=%v, want errors.Is ErrUnexpectedEOF", err)
140		}
141	}
