143	func TestRestoreCompleteDocArrivingWithFaultIsReadFailure(t *testing.T) {
144		index := txChain(t, []string{"a"}, []string{"b"})
145		blocks, byHash, tip := snapshot(index)
146		raw := exportString(t, index)
147		// The single read hands over a whole, valid snapshot together with the
148		// fault and never signals a clean EOF: the stream failed, so Restore must
149		// not apply it.
150		err := index.Restore(&oneShotReader{data: []byte(raw), err: io.ErrUnexpectedEOF})
151		if errors.Is(err, ErrInvalidSnapshot) {
152			t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
153		}
154		if !errors.Is(err, io.ErrUnexpectedEOF) {
155			t.Fatalf("err=%v, want errors.Is ErrUnexpectedEOF", err)
156		}
157		requireUnchanged(t, index, blocks, byHash, tip)
158	}
