160	// scriptReader delivers each chunk in order, one Read per chunk, pairing the
161	// chunk's bytes with its error exactly as an underlying stream might; once
162	// the chunks run out it ends normally.
163	type scriptReader struct {
164		chunks []scriptChunk
165	}
166	
167	type scriptChunk struct {
168		data string
169		err  error
170	}
171	
172	func (r *scriptReader) Read(p []byte) (int, error) {
173		if len(r.chunks) == 0 {
174			return 0, io.EOF
175		}
176		chunk := r.chunks[0]
177		r.chunks = r.chunks[1:]
178		n := copy(p, chunk.data)
179		return n, chunk.err
180	}
181	
182	// A content error found in bytes that arrived together with a read fault is
183	// still a read failure: the stream failed, so the bytes cannot be trusted to
184	// be the whole document. The same bytes read to a clean end stay content
185	// errors.
186	func TestRestoreContentErrorWithFaultIsReadFailure(t *testing.T) {
187		cases := map[string]string{
188			"unknown top-level field":   `{"version":1,"tip":0,"blocks":[],"extra":0}`,
189			"duplicate top-level field": `{"version":1,"version":1,"tip":0,"blocks":[]}`,
190			"top level not an object":   `["version",1]`,
191		}
192		for name, doc := range cases {
193			t.Run(name, func(t *testing.T) {
194				index := txChain(t, []string{"a"}, []string{"b"})
195				blocks, byHash, tip := snapshot(index)
196				err := index.Restore(&oneShotReader{data: []byte(doc), err: errStorageOffline})
197				if errors.Is(err, ErrInvalidSnapshot) {
198					t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
199				}
200				if !errors.Is(err, errStorageOffline) {
201					t.Fatalf("err=%v, want errors.Is errStorageOffline", err)
202				}
203				if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
204					t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
205				}
206				requireUnchanged(t, index, blocks, byHash, tip)
207	
208				// The same bytes delivered to a clean end report the content
209				// error instead.
210				index = txChain(t, []string{"a"}, []string{"b"})
211				err = index.Restore(strings.NewReader(doc))
212				if !errors.Is(err, ErrInvalidSnapshot) {
213					t.Fatalf("clean EOF: err=%v, want ErrInvalidSnapshot", err)
214				}
215			})
216		}
217	}
218	
219	// Trailing data after the object is a read failure when the read that fetched
220	// those bytes already reported the fault, whether the fault arrived with the
221	// object's final bytes or only with the trailing ones.
222	func TestRestoreTrailingDataWithFaultIsReadFailure(t *testing.T) {
223		index := txChain(t, []string{"a"}, []string{"b"})
224		raw := exportString(t, index)
225		cases := map[string]io.Reader{
226			"fault with the trailing bytes": &scriptReader{chunks: []scriptChunk{
227				{data: raw},
228				{data: " 2", err: io.ErrUnexpectedEOF},
229			}},
230			"fault with the whole stream": &oneShotReader{
231				data: []byte(raw + " 2"),
232				err:  errStorageOffline,
233			},
234		}
235		for name, r := range cases {
236			t.Run(name, func(t *testing.T) {
237				index := txChain(t, []string{"a"}, []string{"b"})
238				blocks, byHash, tip := snapshot(index)
239				err := index.Restore(r)
240				if errors.Is(err, ErrInvalidSnapshot) {
241					t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
242				}
243				if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
244					t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
245				}
246				requireUnchanged(t, index, blocks, byHash, tip)
247			})
248		}
249	
250		// The same trailing bytes read to a clean end stay a content error.
251		index = txChain(t, []string{"a"}, []string{"b"})
252		if err := index.Restore(strings.NewReader(raw + " 2")); !errors.Is(err, ErrInvalidSnapshot) {
253			t.Fatalf("clean EOF: err=%v, want ErrInvalidSnapshot", err)
254		}
255	}
