257	// Only a fault already received wins. A content error found before the reader
258	// has reported any failure rejects the snapshot as invalid right away, without
259	// reading ahead to look for a fault.
260	func TestRestoreContentErrorBeforeFaultStaysInvalid(t *testing.T) {
261		index := txChain(t, []string{"a"}, []string{"b"})
262		blocks, byHash, tip := snapshot(index)
263		err := index.Restore(&scriptReader{chunks: []scriptChunk{
264			{data: `{"version":1,"extra":0,"tip":0,"blocks":[]}`},
265			{err: errStorageOffline},
266		}})
267		if !errors.Is(err, ErrInvalidSnapshot) {
268			t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
269		}
270		if errors.Is(err, errStorageOffline) {
271			t.Fatalf("err=%v, must not read ahead into the fault", err)
272		}
273		requireUnchanged(t, index, blocks, byHash, tip)
274	}
