276	func TestRestoreReadFailureKeepsChainAndCursor(t *testing.T) {
277		index := txChain(t, []string{"a"}, []string{"b"}, []string{"c"})
278		first, err := index.QueryTxs(TxQuery{PageSize: 1})
279		if err != nil {
280			t.Fatal(err)
281		}
282		cursor := first.NextCursor
283		if cursor == "" {
284			t.Fatal("expected a continuation cursor")
285		}
286		blocks, byHash, tip := snapshot(index)
287	
288		err = index.Restore(&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF})
289		if !errors.Is(err, io.ErrUnexpectedEOF) || errors.Is(err, ErrInvalidSnapshot) {
290			t.Fatalf("err=%v, want a read failure distinct from ErrInvalidSnapshot", err)
291		}
292		requireUnchanged(t, index, blocks, byHash, tip)
293	
294		// The pre-failure cursor keeps paging the original chain; the failed read
295		// must not be reported as ErrQueryChanged.
296		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
297		var all []TxHit
298		for _, page := range pages {
299			all = append(all, page.Hits...)
300		}
301		want := []TxHit{
302			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
303			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
304		}
305		if !reflect.DeepEqual(all, want) {
306			t.Fatalf("hits after read failure=%v, want %v", all, want)
307		}
