310	// eofWrapErr is an io.EOF carrying storage-side context: errors.Is matches
311	// io.EOF, but it is not the bare sentinel the decoder takes for a normal end
312	// of input.
313	type eofWrapErr struct{ err error }
314	
315	func (e *eofWrapErr) Error() string { return "storage at EOF: " + e.err.Error() }
316	func (e *eofWrapErr) Unwrap() error { return e.err }
317	
318	// oneBlockV1 is a complete, valid one-block version-1 snapshot; restored over
319	// a multi-block index it would visibly shorten the chain if it were applied.
320	const oneBlockV1 = `{"version":1,"tip":1,"blocks":[` +
321		`{"height":1,"hash":"g1","parent":"g","txs":[]}]}`
322	
323	// oneBlockV2 is the same snapshot in the version-2 layout.
324	const oneBlockV2 = `{"version":2,"tip":1,"blocks":[` +
325		`{"height":1,"hash":"g1","parent":"g","txs":[],"timestamp":null}]}`
326	
327	// Only the bare io.EOF the reader returns directly marks the normal end of a
328	// restore stream. An io.EOF carrying context, and a combined error joining
329	// io.EOF with a storage fault (as errors.Join produces), are read failures
330	// whether they arrive alone or together with usable bytes, and whether those
331	// bytes already form a complete JSON object or only a prefix.
332	func TestRestoreJoinedOrWrappedEOFIsReadFailure(t *testing.T) {
333		joined := errors.Join(io.EOF, errStorageOffline)
334		wrapped := &eofWrapErr{err: io.EOF}
335		cases := map[string]struct {
336			r         io.Reader
337			wantFault bool
338		}{
339			"joined EOF and fault with a complete snapshot": {
340				&oneShotReader{data: []byte(oneBlockV1), err: joined}, true,
341			},
342			"joined EOF and fault with a half snapshot": {
343				&oneShotReader{data: []byte(halfSnapshot), err: joined}, true,
344			},
345			"joined EOF and fault without bytes": {
346				&oneShotReader{err: joined}, true,
347			},
348			"wrapped EOF with a complete snapshot": {
349				&oneShotReader{data: []byte(oneBlockV1), err: wrapped}, false,
350			},
351			"wrapped EOF with a half snapshot": {
352				&oneShotReader{data: []byte(halfSnapshot), err: wrapped}, false,
353			},
354			"wrapped EOF without bytes": {
355				&oneShotReader{err: wrapped}, false,
356			},
357		}
358		for name, tc := range cases {
359			t.Run(name, func(t *testing.T) {
360				index := txChain(t, []string{"a"}, []string{"b"})
361				blocks, byHash, tip := snapshot(index)
362				err := index.Restore(tc.r)
363				if err == nil {
364					t.Fatal("expected a read failure, got success")
365				}
366				if errors.Is(err, ErrInvalidSnapshot) {
367					t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
368				}
369				if !errors.Is(err, io.EOF) {
370					t.Fatalf("err=%v, caller must still errors.Is the end marker", err)
371				}
372				if tc.wantFault && !errors.Is(err, errStorageOffline) {
373					t.Fatalf("err=%v, caller must errors.Is the storage fault", err)
374				}
375				if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
376					t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
377				}
378				requireUnchanged(t, index, blocks, byHash, tip)
379			})
380		}
381	}
382	
383	// The scenario from the fault report: a three-block chain fed a valid
384	// one-block snapshot whose final bytes arrive together with a combined
385	// io.EOF+storage error must fail as a read failure with the whole chain
386	// intact — never shorten the chain first and then error — and a cursor taken
387	// before the attempt keeps paging the original transactions.
388	func TestRestoreJoinedEOFReadFailureKeepsChainAndCursor(t *testing.T) {
389		index := txChain(t, []string{"a"}, []string{"b"}, []string{"c"})
390		first, err := index.QueryTxs(TxQuery{PageSize: 1})
391		if err != nil {
392			t.Fatal(err)
393		}
394		cursor := first.NextCursor
395		if cursor == "" {
396			t.Fatal("expected a continuation cursor")
397		}
398		blocks, byHash, tip := snapshot(index)
399	
400		err = index.Restore(&oneShotReader{
401			data: []byte(oneBlockV1),
402			err:  errors.Join(io.EOF, errStorageOffline),
403		})
404		if err == nil {
405			t.Fatal("expected a read failure, got success")
406		}
407		if errors.Is(err, ErrInvalidSnapshot) {
408			t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
409		}
410		if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
411			t.Fatalf("err=%v, want errors.Is both io.EOF and the storage fault", err)
412		}
413		requireUnchanged(t, index, blocks, byHash, tip)
414	
415		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
416		var all []TxHit
417		for _, page := range pages {
418			all = append(all, page.Hits...)
419		}
420		want := []TxHit{
421			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
422			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
423		}
424		if !reflect.DeepEqual(all, want) {
425			t.Fatalf("hits after read failure=%v, want %v", all, want)
426		}
427	}
