68	// shuffledV2Snapshot is the version-2 counterpart: tip precedes blocks, the
69	// block fields are reordered (timestamp first in block 1, last in block 2),
70	// the block-1 time is null while block 2 carries a real zero, and escapes are
71	// mixed into the identifiers.
72	func shuffledV2Snapshot() string {
73		return "{\n  \"tip\" : 2,\n" +
74			"  \"blocks\" : [\n" +
75			"    { \"timestamp\" : null, \"hash\" : \"" + uescape('h') + "1\", \"parent\" : \"g\", \"height\" : 1, \"txs\" : [ \"a\", \"\" ] },\n" +
76			"    { \"height\" : 2, \"hash\" : \"h2\", \"parent\" : \"h" + uescape('1') + "\", \"txs\" : [\"b\"], \"timestamp\" : 0 }\n" +
77			"  ],\n  \"version\" : 2\n}\n"
