149	func TestRestoreReshapedV1TextMatchesCanonicalChain(t *testing.T) {
150		index := New()
151		if err := index.Restore(strings.NewReader(shuffledV1Snapshot())); err != nil {
152			t.Fatalf("reshaped snapshot rejected: %v", err)
153		}
154		requireSameChain(t, index, buildReferenceChain())
155	
156		// Querying by the decoded identifier finds every occurrence at its
157		// original position: "tx-中" appears twice in block 1 and once in block 2,
158		// the empty identifier at position 3, and "other" at position 1.
159		requireTxQuery(t, index, "tx-中", []TxHit{
160			{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 0},
161			{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 2},
162			{Height: 2, BlockHash: "h2", TxID: "tx-中", Position: 0},
163		}, 3, 2)
164		requireTxQuery(t, index, "", []TxHit{
165			{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
166		}, 1, 1)
167		requireTxQuery(t, index, "other", []TxHit{
168			{Height: 1, BlockHash: "h1", TxID: "other", Position: 1},
169		}, 1, 1)
170	
171		// Case and whitespace inside an identifier are part of the identifier;
172		// accepting text variants must not merge originally distinct ids.
173		for _, other := range []string{" tx-中", "tx-中 ", "TX-中", "tx-中x"} {
174			requireTxQuery(t, index, other, nil, 0, 0)
175		}
176	
177		// Without a filter the transactions come back in the decoded order.
178		page, err := index.QueryTxs(TxQuery{})
179		if err != nil {
180			t.Fatal(err)
181		}
182		wantAll := []TxHit{
183			{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 0},
184			{Height: 1, BlockHash: "h1", TxID: "other", Position: 1},
185			{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 2},
186			{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
187			{Height: 2, BlockHash: "h2", TxID: "tx-中", Position: 0},
188		}
189		if !reflect.DeepEqual(page.Hits, wantAll) {
190			t.Fatalf("unfiltered hits=%+v, want %+v", page.Hits, wantAll)
191		}
192		if page.TotalMatches != 5 || page.MatchedBlocks != 2 {
193			t.Fatalf("unfiltered totals=%d/%d, want 5/2", page.TotalMatches, page.MatchedBlocks)
194		}
195	}
