490			// decoded identifier; duplicates are kept in order.
491			requireTxQuery(t, index, "id-中", []TxHit{
492				{Height: 1, BlockHash: "h1", TxID: "id-中", Position: 0},
493				{Height: 1, BlockHash: "h1", TxID: "id-中", Position: 1},
494			}, 2, 1)
