1	package indexroom
2	
3	import (
4		"encoding/json"
5		"errors"
6		"reflect"
7		"strings"
8		"sync"
9		"testing"
10	)
11	
12	// This file is the regression guard for the ordering between a Restore that
13	// is still reading its input and block ingestion (Append) that succeeds while
14	// that read is incomplete. Restore consumes and validates the whole stream
15	// before taking index.mu, so ingestion and querying stay open for the whole
16	// read window; the two deterministic outcomes then rest on the existing
17	// whole-replacement rules:
18	//
19	//   - restore success: the main chain is decided by the snapshot alone. A
20	//     block appended while the restore was reading, at a height above the
21	//     snapshot tip, disappears together with the old chain; appends made
22	//     afterwards extend the snapshot chain from its own tip and hash;
23	//   - restore failure (an invalid block found only at the end, or a read
24	//     fault the underlying reader reports at the end): the old chain and the
25	//     block ingested during the read both stay in effect, and Export
26	//     describes that extended chain. Nothing of the snapshot's valid prefix
27	//     survives.
28	//
29	// Scenario:
30	//
31	//	Old main chain already ingested, tip 2:
32	//	  h1 parent g  txs [a]
33	//	  h2 parent h1 txs [b]
34	//	Block appended while the restore is parked mid-read:
35	//	  h3 parent h2 txs [c]           // height 3, above the snapshot tip
36	//	Version-1 snapshot, tip 2, two blocks with different content:
37	//	  j1 parent g  txs [x, z, x]     // x twice in one block: both occurrences
38	//	  j2 parent j1 txs [y]           // keep their original in-block positions
39	//
40	// The two chains share neither a hash nor a transaction id, so a query answer
41	// can never be explained by both, and the appended h3 is distinguishable from
42	// every other height. During the read window the chain must answer
43	// {a, b, c} with upper height 3 — never an already-read j1 record mixed in;
44	// after a successful restore it must answer {x, z, x, y} with upper height 2
45	// and no trace of h1, h2, or h3; after either failure it must still answer
46	// {a, b, c} with upper height 3.
47	
48	// restoreIngestSnapshot is the valid version-1 wire form of the two-block
49	// snapshot chain (j1, j2).
50	const restoreIngestSnapshot = `{"version":1,"tip":2,"blocks":[` +
51		`{"height":1,"hash":"j1","parent":"g","txs":["x","z","x"]},` +
52		`{"height":2,"hash":"j2","parent":"j1","txs":["y"]}` +
53		`]}`
54	
55	// restoreIngestBrokenSnapshot is identical to restoreIngestSnapshot except
56	// that the LAST block carries a wrong parent link, so its invalidity is
57	// discovered only at the end of the document, after the whole valid prefix
58	// (including j1) has been read.
59	const restoreIngestBrokenSnapshot = `{"version":1,"tip":2,"blocks":[` +
60		`{"height":1,"hash":"j1","parent":"g","txs":["x","z","x"]},` +
61		`{"height":2,"hash":"j2","parent":"j1-broken","txs":["y"]}` +
62		`]}`
63	
64	// restoreIngestCutMarker parks the read between the two block objects: j1 has
65	// already been fully consumed, j2 has not arrived, and Restore holds no lock.
66	const restoreIngestCutMarker = `{"height":2`
67	
68	func restoreIngestOldChainBlocks() []Block {
69		return []Block{
70			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"a"}},
71			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"b"}},
72		}
73	}
74	
75	// restoreIngestAppendedBlock is the legal append that lands while the restore
76	// is still waiting for the rest of its input.
77	func restoreIngestAppendedBlock() Block {
78		return Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"c"}}
79	}
80	
81	func buildRestoreIngestChain(t *testing.T) *Index {
82		t.Helper()
83		index := New()
84		for _, b := range restoreIngestOldChainBlocks() {
85			if err := index.Append(b); err != nil {
86				t.Fatalf("setup append at height %d: %v", b.Height, err)
87			}
88		}
89		return index
90	}
