92	// restoreIngestExportDoc is the minimal schema used to inspect Export output.
93	type restoreIngestExportDoc struct {
94		Version int64 `json:"version"`
95		Tip     int64 `json:"tip"`
96		Blocks  []struct {
97			Height int64    `json:"height"`
98			Hash   string   `json:"hash"`
99			Parent string   `json:"parent"`
100			Txs    []string `json:"txs"`
101		} `json:"blocks"`
102	}
103	
104	func mustRestoreIngestExport(t *testing.T, index *Index) restoreIngestExportDoc {
105		t.Helper()
106		raw := exportString(t, index)
107		var doc restoreIngestExportDoc
108		if err := json.Unmarshal([]byte(raw), &doc); err != nil {
109			t.Fatalf("exported snapshot does not parse: %v\n%s", err, raw)
110		}
111		return doc
112	}
113	
114	func restoreIngestQuery(t *testing.T, index *Index, ids ...string) TxPage {
115		t.Helper()
116		page, err := index.QueryTxs(TxQuery{TxIDs: ids})
117		if err != nil {
118			t.Fatalf("query failed: %v", err)
119		}
120		return page
121	}
122	
123	// The fixture the regression rests on, checked directly: the wire documents
124	// parse to the intended chains, the broken document is invalid only in its
125	// last block, h3 extends the old chain, and the two chains share neither a
126	// hash nor a transaction id.
127	func TestRestoreIngestFixtureSemantics(t *testing.T) {
128		tip, blocks, err := parseSnapshot(strings.NewReader(restoreIngestSnapshot))
129		if err != nil {
130			t.Fatalf("valid snapshot must parse: %v", err)
131		}
132		if tip != 2 || len(blocks) != 2 {
133			t.Fatalf("parsed snapshot tip=%d blocks=%d, want tip 2 with 2 blocks", tip, len(blocks))
134		}
135		wantJ1 := Block{Height: 1, Hash: "j1", Parent: "g", Txs: []string{"x", "z", "x"}}
136		wantJ2 := Block{Height: 2, Hash: "j2", Parent: "j1", Txs: []string{"y"}}
137		if !reflect.DeepEqual(blocks[0], wantJ1) || !reflect.DeepEqual(blocks[1], wantJ2) {
138			t.Fatalf("parsed blocks=%v, want [%+v %+v]", blocks, wantJ1, wantJ2)
139		}
140	
141		// The broken document is well-formed right up to its last block's parent
142		// linkage, which is exactly the "invalidity discovered at the end" case.
143		if _, _, err := parseSnapshot(strings.NewReader(restoreIngestBrokenSnapshot)); !errors.Is(err, ErrInvalidSnapshot) {
144			t.Fatalf("broken snapshot err=%v, want ErrInvalidSnapshot", err)
145		} else if !strings.Contains(err.Error(), "does not link to its parent") {
146			t.Fatalf("broken snapshot must fail on the last block's parent link: %v", err)
147		}
148	
149		index := buildRestoreIngestChain(t)
150		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
151			t.Fatalf("h3 must extend the old chain: %v", err)
152		}
153		if index.Tip != 3 || index.Blocks[3].Hash != "h3" || index.Blocks[3].Parent != "h2" {
154			t.Fatalf("chain after h3 append: tip=%d block3=%+v", index.Tip, index.Blocks[3])
155		}
156	
157		// No hash and no transaction identifier is explainable by both chains,
158		// and h3 is outside the snapshot's height range.
159		for _, hash := range []string{"h1", "h2", "h3"} {
160			if hash == "j1" || hash == "j2" {
161				t.Fatalf("fixture hash %q is shared between the chains", hash)
162			}
163		}
164		oldIDs := map[string]bool{"a": true, "b": true, "c": true}
165		for _, id := range []string{"x", "y", "z"} {
166			if oldIDs[id] {
167				t.Fatalf("fixture tx %q is shared between the chains", id)
168			}
169		}
170	}
171	
172	// While the restore is still waiting for the remainder of its input it holds
173	// no lock: a legal append completes at once, the new transaction is
174	// immediately queryable, and the query's upper height reflects the appended
175	// tip. The snapshot block already read must not appear early, and old-chain
176	// and snapshot transactions must never share one answer. Both the append and
177	// the query finish before the restore does.
178	func TestAppendAndQueryWhileRestoreWaitsForInput(t *testing.T) {
179		index := buildRestoreIngestChain(t)
180		reader := newGatedReader(t, restoreIngestSnapshot, restoreIngestCutMarker)
181	
182		restoreDone := make(chan error, 1)
183		go func() {
184			restoreDone <- index.Restore(reader)
185		}()
186		<-reader.entered // j1 consumed, j2 not yet arrived; Restore holds no lock
187	
188		// Existing append rules are still enforced during the read window: a
189		// block not extending the current tip is rejected and changes nothing.
190		blocks, byHash, tip := snapshot(index)
191		if err := index.Append(Block{Height: 3, Hash: "r3", Parent: "h1", Txs: []string{"r"}}); err == nil {
192			t.Fatal("append with a non-tip parent must be rejected while the restore reads")
193		}
194		requireUnchanged(t, index, blocks, byHash, tip)
195	
196		// The legal append extends the OLD chain tip and returns before the
197		// restore ends.
198		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
199			t.Fatalf("append while restore is reading: %v", err)
200		}
201		select {
202		case err := <-restoreDone:
203			t.Fatalf("restore returned while its input was still gated: %v", err)
204		default:
205		}
206	
207		// The appended transaction is immediately visible, at its original
208		// position, and the pinned upper height follows the appended tip.
209		page := restoreIngestQuery(t, index)
210		want := []TxHit{
211			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
212			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
213			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
214		}
215		if !reflect.DeepEqual(page.Hits, want) {
216			t.Fatalf("query during the read window=%v, want old chain plus h3", page.Hits)
217		}
218		if page.ToHeight != 3 || page.TotalMatches != 3 || page.MatchedBlocks != 3 {
219			t.Fatalf("upper height and statistics must reflect appended tip 3: %+v", page)
220		}
221	
222		// Already-read snapshot content must not surface early: filtering for
223		// snapshot transactions returns an empty successful page pinned at tip 3.
224		snapshotOnly := restoreIngestQuery(t, index, "x", "y", "z")
225		if len(snapshotOnly.Hits) != 0 || snapshotOnly.ToHeight != 3 {
226			t.Fatalf("snapshot txs visible before the restore applied: %+v", snapshotOnly)
227		}
228	
229		// One filtered answer must never stitch both chains together: the old id
230		// is present, the snapshot id is absent, even though j1 was already read.
231		mixed := restoreIngestQuery(t, index, "a", "x")
232		if !reflect.DeepEqual(mixed.Hits, []TxHit{{Height: 1, BlockHash: "h1", TxID: "a", Position: 0}}) {
233			t.Fatalf("old and snapshot txs mixed into one answer: %+v", mixed.Hits)
234		}
235	
236		// The already-read snapshot block has no presence in the index, and the
237		// query above completed while the restore was still blocked.
238		for _, leaked := range []string{"j1", "j2"} {
239			if _, ok := index.ByHash[leaked]; ok {
240				t.Fatalf("snapshot hash %s appeared before the restore applied", leaked)
241			}
242		}
243		select {
244		case err := <-restoreDone:
245			t.Fatalf("restore returned before its input was released: %v", err)
246		default:
247		}
248	
249		close(reader.release)
250		if err := <-restoreDone; err != nil {
251			t.Fatalf("restore after release failed: %v", err)
252		}
253	}
254	
255	// Once the complete, valid snapshot arrives the whole-replacement rule wins:
256	// the final tip is the snapshot tip (2) even though height 3 was appended
257	// during the read, every returned transaction (with its original in-block
258	// position) is a snapshot transaction, and a fresh Export contains only the
259	// snapshot chain. Appends afterwards continue from the new tip and hash;
260	// requests still parented by the old tip or by the block appended mid-read
261	// are rejected by the existing rules and cannot revive the replaced chain.
262	func TestSuccessfulRestoreAfterIngestionReplacesWholeChain(t *testing.T) {
263		index := buildRestoreIngestChain(t)
264		reader := newGatedReader(t, restoreIngestSnapshot, restoreIngestCutMarker)
265		restoreDone := make(chan error, 1)
266		go func() {
267			restoreDone <- index.Restore(reader)
268		}()
269		<-reader.entered
270		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
271			t.Fatalf("append while restore is reading: %v", err)
272		}
273		page := restoreIngestQuery(t, index)
274		if page.ToHeight != 3 || len(page.Hits) != 3 {
275			t.Fatalf("setup: appended block not visible during the read: %+v", page)
276		}
277	
278		close(reader.release)
279		if err := <-restoreDone; err != nil {
280			t.Fatalf("restore must succeed on complete valid input: %v", err)
281		}
282	
283		// The snapshot decides the chain completely: tip 2, exactly j1 and j2.
284		if index.Tip != 2 {
285			t.Fatalf("tip after restore=%d, want snapshot tip 2 (height 3 appended during the read must vanish)", index.Tip)
286		}
287		wantIndex := chain(t,
288			Block{Height: 1, Hash: "j1", Parent: "g", Txs: []string{"x", "z", "x"}},
289			Block{Height: 2, Hash: "j2", Parent: "j1", Txs: []string{"y"}},
290		)
291		if !reflect.DeepEqual(index.Blocks, wantIndex.Blocks) || !reflect.DeepEqual(index.ByHash, wantIndex.ByHash) {
292			t.Fatalf("chain after restore is not exactly the snapshot chain:\nblocks=%v\nbyHash=%v", index.Blocks, index.ByHash)
293		}
294		for _, leaked := range []int64{3} {
295			if _, ok := index.Blocks[leaked]; ok {
296				t.Fatalf("height %d appended during the read survived the restore", leaked)
297			}
298		}
299		for _, leaked := range []string{"h1", "h2", "h3"} {
300			if _, ok := index.ByHash[leaked]; ok {
301				t.Fatalf("replaced hash %s survived the restore", leaked)
302			}
303		}
304	
305		// Queries return snapshot transactions at their original block positions;
306		// the duplicate x keeps both occurrences, and every old/ingested tx is
307		// gone.
308		page = restoreIngestQuery(t, index)
309		wantHits := []TxHit{
310			{Height: 1, BlockHash: "j1", TxID: "x", Position: 0},
311			{Height: 1, BlockHash: "j1", TxID: "z", Position: 1},
312			{Height: 1, BlockHash: "j1", TxID: "x", Position: 2},
313			{Height: 2, BlockHash: "j2", TxID: "y", Position: 0},
314		}
315		if !reflect.DeepEqual(page.Hits, wantHits) {
316			t.Fatalf("post-restore hits=%v, want snapshot transactions at their original positions", page.Hits)
317		}
318		if page.ToHeight != 2 || page.TotalMatches != 4 || page.MatchedBlocks != 2 {
319			t.Fatalf("post-restore page must describe the snapshot chain: %+v", page)
320		}
321		oldOnly := restoreIngestQuery(t, index, "a", "b", "c")
322		if len(oldOnly.Hits) != 0 {
323			t.Fatalf("old and mid-read transactions survived the restore: %+v", oldOnly.Hits)
324		}
325		dupX := restoreIngestQuery(t, index, "x")
326		if !reflect.DeepEqual(dupX.Hits, []TxHit{
327			{Height: 1, BlockHash: "j1", TxID: "x", Position: 0},
328			{Height: 1, BlockHash: "j1", TxID: "x", Position: 2},
329		}) {
330			t.Fatalf("duplicate snapshot tx must keep both in-block positions: %+v", dupX.Hits)
331		}
332	
333		// A fresh export contains exactly the snapshot main chain: no height 3
334		// and no replaced hash anywhere in the bytes.
335		doc := mustRestoreIngestExport(t, index)
336		if doc.Version != 1 || doc.Tip != 2 || len(doc.Blocks) != 2 {
337			t.Fatalf("export after restore=%+v, want version 1, tip 2, two blocks", doc)
338		}
339		for i, want := range []struct {
340			height int64
341			hash   string
342			parent string
343			txs    []string
344		}{
345			{1, "j1", "g", []string{"x", "z", "x"}},
346			{2, "j2", "j1", []string{"y"}},
347		} {
348			got := doc.Blocks[i]
349			if got.Height != want.height || got.Hash != want.hash || got.Parent != want.parent ||
350				!reflect.DeepEqual(got.Txs, want.txs) {
351				t.Fatalf("exported block %d=%+v, want %+v", i+1, got, want)
352			}
353		}
354		raw := exportString(t, index)
355		for _, gone := range []string{"h1", "h2", "h3", `"c"`} {
356			if strings.Contains(raw, gone) {
357				t.Fatalf("export after restore still contains %q:\n%s", gone, raw)
358			}
359		}
360	
361		// Requests still parented by the pre-restore tip (h2) or by the block
362		// appended during the read (h3) follow the existing rejection rules and
363		// must not revive the replaced chain.
364		stateBlocks, stateByHash, stateTip := snapshot(index)
365		for _, stale := range []Block{
366			{Height: 3, Hash: "r3", Parent: "h2", Txs: []string{"r"}}, // parented by the old tip
367			{Height: 4, Hash: "r4", Parent: "h3", Txs: []string{"r"}}, // parented by the mid-read block
368		} {
369			if err := index.Append(stale); err == nil {
370				t.Fatalf("stale append %+v must be rejected after the restore", stale)
371			}
372			requireUnchanged(t, index, stateBlocks, stateByHash, stateTip)
373		}
374	
375		// Ingestion continues from the new chain tip and hash.
376		continued := Block{Height: 3, Hash: "k3", Parent: "j2", Txs: []string{"w"}}
377		if err := index.Append(continued); err != nil {
378			t.Fatalf("append continuing the snapshot chain: %v", err)
379		}
380		if index.Tip != 3 || index.Blocks[3].Hash != "k3" || index.Blocks[3].Parent != "j2" {
381			t.Fatalf("chain after continuation: tip=%d block3=%+v", index.Tip, index.Blocks[3])
382		}
383		gotW := restoreIngestQuery(t, index, "w")
384		if !reflect.DeepEqual(gotW.Hits, []TxHit{{Height: 3, BlockHash: "k3", TxID: "w", Position: 0}}) {
385			t.Fatalf("continued block transaction=%+v, want w@k3#0", gotW.Hits)
386		}
387		// A block still citing h3 (the vanished mid-read tip) cannot extend the
388		// chain even at the right height.
389		if err := index.Append(Block{Height: 4, Hash: "r4", Parent: "h3", Txs: []string{"r"}}); err == nil {
390			t.Fatal("append parented by the vanished h3 must be rejected")
391		}
392		if index.Tip != 3 || index.Blocks[3].Hash != "k3" {
393			t.Fatalf("rejected append altered the restored chain: tip=%d block3=%+v", index.Tip, index.Blocks[3])
394		}
395	}
396	
397	// After a legal append during the read window, an invalid block discovered
398	// only at the end of the input fails the restore with ErrInvalidSnapshot and
399	// leaves the old chain plus the appended block exactly as they were; the
400	// snapshot's valid prefix leaves nothing behind.
401	func TestRestoreRejectedByLastBlockKeepsIngestedChain(t *testing.T) {
402		index := buildRestoreIngestChain(t)
403		reader := newGatedReader(t, restoreIngestBrokenSnapshot, restoreIngestCutMarker)
404		restoreDone := make(chan error, 1)
405		go func() {
406			restoreDone <- index.Restore(reader)
407		}()
408		<-reader.entered
409		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
410			t.Fatalf("append while restore is reading: %v", err)
411		}
412		page := restoreIngestQuery(t, index)
413		if page.ToHeight != 3 || len(page.Hits) != 3 {
414			t.Fatalf("setup: appended block not visible during the read: %+v", page)
415		}
416	
417		close(reader.release)
418		if err := <-restoreDone; !errors.Is(err, ErrInvalidSnapshot) {
419			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
420		}
421	
422		// The old chain and the block ingested during the read both survive; no
423		// snapshot block was left behind.
424		wantIndex := chain(t, append(restoreIngestOldChainBlocks(), restoreIngestAppendedBlock())...)
425		if !reflect.DeepEqual(index.Blocks, wantIndex.Blocks) || !reflect.DeepEqual(index.ByHash, wantIndex.ByHash) || index.Tip != 3 {
426			t.Fatalf("chain after rejected restore:\nblocks=%v\nbyHash=%v tip=%d\nwant the old chain plus h3",
427				index.Blocks, index.ByHash, index.Tip)
428		}
429		for _, leaked := range []string{"j1", "j2"} {
430			if _, ok := index.ByHash[leaked]; ok {
431				t.Fatalf("snapshot hash %s from the valid prefix was left indexed", leaked)
432			}
433		}
434	
435		page = restoreIngestQuery(t, index)
436		wantHits := []TxHit{
437			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
438			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
439			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
440		}
441		if !reflect.DeepEqual(page.Hits, wantHits) || page.ToHeight != 3 {
442			t.Fatalf("query after rejected restore=%+v, want the complete old chain including h3", page)
443		}
444		if len(restoreIngestQuery(t, index, "x", "y", "z").Hits) != 0 {
445			t.Fatal("snapshot transactions leaked in after the rejected restore")
446		}
447	
448		// Export reflects the chain as extended by the mid-read append, with no
449		// snapshot hash or transaction in the document.
450		doc := mustRestoreIngestExport(t, index)
451		if doc.Version != 1 || doc.Tip != 3 || len(doc.Blocks) != 3 {
452			t.Fatalf("export after rejected restore=%+v, want version 1, tip 3, three blocks", doc)
453		}
454		for i, want := range []struct {
455			height int64
456			hash   string
457			parent string
458			txs    []string
459		}{
460			{1, "h1", "g", []string{"a"}},
461			{2, "h2", "h1", []string{"b"}},
462			{3, "h3", "h2", []string{"c"}},
463		} {
464			got := doc.Blocks[i]
465			if got.Height != want.height || got.Hash != want.hash || got.Parent != want.parent ||
466				!reflect.DeepEqual(got.Txs, want.txs) {
467				t.Fatalf("exported block %d=%+v, want %+v", i+1, got, want)
468			}
469		}
470		if raw := exportString(t, index); strings.Contains(raw, "j1") || strings.Contains(raw, "j2") {
471			t.Fatalf("export after rejected restore contains snapshot hashes:\n%s", raw)
472		}
473	}
474	
475	// gatedTailFaultReader delivers the prefix, parks until release, then hands
476	// over the remaining bytes together with fault on the first read after the
477	// gate and the fault on every later read. It models a stream whose storage
478	// fails once the restore is allowed to run to the end, even when the buffered
479	// tail already completes the document.
480	type gatedTailFaultReader struct {
481		data    []byte
482		prefix  int
483		off     int
484		fault   error
485		entered chan struct{}
486		release chan struct{}
487		parked  bool
488		once    sync.Once
489	}
490	
491	func newGatedTailFaultReader(t *testing.T, data, cutMarker string, fault error) *gatedTailFaultReader {
492		t.Helper()
493		prefix := strings.Index(data, cutMarker)
494		if prefix <= 0 {
495			t.Fatalf("test setup: cut marker %q not found in %q", cutMarker, data)
496		}
497		if fault == nil {
498			t.Fatal("test setup: gated tail fault reader requires a fault")
499		}
500		return &gatedTailFaultReader{
501			data:    []byte(data),
502			prefix:  prefix,
503			fault:   fault,
504			entered: make(chan struct{}),
505			release: make(chan struct{}),
506		}
507	}
508	
509	func (r *gatedTailFaultReader) Read(p []byte) (int, error) {
510		if r.off < r.prefix {
511			n := copy(p, r.data[r.off:r.prefix])
512			r.off += n
513			return n, nil
514		}
515		if !r.parked {
516			r.parked = true
517			r.once.Do(func() { close(r.entered) })
518			<-r.release
519		}
520		if r.off < len(r.data) {
521			n := copy(p, r.data[r.off:])
522			r.off += n
523			// Bytes and fault in one read, exactly as a failing storage read can
524			// deliver them; snapshotReader withholds the fault until next time.
525			return n, r.fault
526		}
527		return 0, r.fault
528	}
529	
530	// After a legal append during the read window, a read fault reported at the
531	// end of the input — together with the tail bytes of an otherwise complete
532	// snapshot — fails the restore as a read failure carrying the recognizable
533	// original fault (never ErrInvalidSnapshot) and leaves the old chain plus the
534	// appended block in effect, in queries and in export.
535	func TestRestoreReadFaultAfterIngestionKeepsChainAndFault(t *testing.T) {
536		index := buildRestoreIngestChain(t)
537		// The valid snapshot completes in the faulted tail, proving a read
538		// failure outranks an already-complete document rather than applying it.
539		reader := newGatedTailFaultReader(t, restoreIngestSnapshot, restoreIngestCutMarker, errStorageOffline)
540		done := make(chan error, 1)
541		go func() {
542			done <- index.Restore(reader)
543		}()
544		<-reader.entered
545		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
546			t.Fatalf("append while restore is reading: %v", err)
547		}
548		page := restoreIngestQuery(t, index)
549		if page.ToHeight != 3 || len(page.Hits) != 3 {
550			t.Fatalf("setup: appended block not visible during the read: %+v", page)
551		}
552	
553		close(reader.release)
554		err := <-done
555		if err == nil {
556			t.Fatal("restore with a faulted tail must fail")
557		}
558		if errors.Is(err, ErrInvalidSnapshot) {
559			t.Fatalf("err=%v, a read fault must not be reported as ErrInvalidSnapshot", err)
560		}
561		if !errors.Is(err, errStorageOffline) {
562			t.Fatalf("err=%v, caller must still errors.Is the original fault", err)
563		}
564		if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
565			t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
566		}
567	
568		// The old chain and the block ingested during the read both survive; the
569		// complete, valid-looking snapshot is not applied and leaves nothing.
570		wantIndex := chain(t, append(restoreIngestOldChainBlocks(), restoreIngestAppendedBlock())...)
571		if !reflect.DeepEqual(index.Blocks, wantIndex.Blocks) || !reflect.DeepEqual(index.ByHash, wantIndex.ByHash) || index.Tip != 3 {
572			t.Fatalf("chain after read fault:\nblocks=%v\nbyHash=%v tip=%d\nwant the old chain plus h3",
573				index.Blocks, index.ByHash, index.Tip)
574		}
575		for _, leaked := range []string{"j1", "j2"} {
576			if _, ok := index.ByHash[leaked]; ok {
577				t.Fatalf("snapshot hash %s was left indexed after the read fault", leaked)
578			}
579		}
580		page = restoreIngestQuery(t, index)
581		if !reflect.DeepEqual(page.Hits, []TxHit{
582			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
583			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
584			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
585		}) || page.ToHeight != 3 {
586			t.Fatalf("query after read fault=%+v, want the complete old chain including h3", page)
587		}
588		doc := mustRestoreIngestExport(t, index)
589		if doc.Version != 1 || doc.Tip != 3 || len(doc.Blocks) != 3 {
590			t.Fatalf("export after read fault=%+v, want version 1, tip 3, three blocks", doc)
591		}
592		if doc.Blocks[2].Hash != "h3" || doc.Blocks[2].Parent != "h2" {
593			t.Fatalf("export after read fault must end at the appended h3: %+v", doc.Blocks[2])
594		}
595		if raw := exportString(t, index); strings.Contains(raw, "j1") || strings.Contains(raw, "j2") {
596			t.Fatalf("export after read fault contains snapshot hashes:\n%s", raw)
597		}
598	}
